mapper.select:
SELECT , CASE WHEN t.task_type = 'EXECUTE_CYCLE' THEN IFNULL(child.totalCount, 0) ELSE 1 END AS caseCount, CASE WHEN t.task_type = 'EXECUTE_CYCLE' THEN IFNULL(child.finishedCount, 0) ELSE IF(t.task_status IN ('COMPLETED','FAILED','CANCELLED'), 1, 0) END AS completedCount, CASE WHEN t.task_type = 'EXECUTE_CYCLE' THEN IFNULL(child.passCount, 0) ELSE IF(latest.result = 'PASS', 1, 0) END AS passCount, CASE WHEN t.task_type = 'EXECUTE_CYCLE' THEN IFNULL(child.failCount, 0) ELSE IF(latest.result = 'FAIL', 1, 0) END AS failCount, CASE WHEN t.task_type = 'EXECUTE_CYCLE' THEN IFNULL(child.blockedCount, 0) ELSE IF(latest.result = 'BLOCKED', 1, 0) END AS blockedCount, CASE WHEN t.task_type = 'EXECUTE_CYCLE' THEN IFNULL(child.skippedCount, 0) ELSE IF(latest.result = 'SKIPPED', 1, 0) END AS skippedCount
LEFT JOIN ( SELECT c.parent_task_id, COUNT(*) AS totalCount, SUM(c.task_status IN ('COMPLETED','FAILED','CANCELLED')) AS finishedCount, SUM(x.result = 'PASS') AS passCount, SUM(x.result = 'FAIL') AS failCount, SUM(x.result = 'BLOCKED') AS blockedCount, SUM(x.result = 'SKIPPED') AS skippedCount FROM dpm_execution_task c LEFT JOIN dpm_test_execution x ON x.id = ( SELECT x2.id FROM dpm_test_execution x2 WHERE x2.task_id = c.id ORDER BY x2.attempt_no DESC LIMIT 1 ) WHERE c.parent_task_id IS NOT NULL GROUP BY c.parent_task_id ) child ON child.parent_task_id = t.id LEFT JOIN dpm_test_execution latest ON latest.id = ( SELECT x3.id FROM dpm_test_execution x3 WHERE x3.task_id = t.id ORDER BY x3.attempt_no DESC LIMIT 1 )
ORDER BY t.created_at DESC, t.id DESC LIMIT #{offset}, #{pageSize}

